import {useStaticQuery, graphql} from 'gatsby';
import React, {Fragment, useState, useEffect, useMemo} from 'react';

import contentTypes from '../util/ContentTypes';
import {STORAGE_KEYS} from '../util/constants';
import {useViewport, useStickyState} from '../util/hooks';
import sortingMethods, {shuffle} from '../util/sorting-methods';
import {capitalize} from '../util/util';
import ContentGrid from './ContentGrid';
import gridDoodles from './GridDoodles';

import './ProjectExplorer.css';

const ProjectExplorer = React.memo(function ProjectExplorer(props) {
	const [nodeTypes, version] = useMemo(() => {
		const nodeTypes = Array.from(
			new Set(props.nodes.map(n => n.type)),
		).sort((a, b) => a.localeCompare(b));
		return [
			nodeTypes,
			`${nodeTypes.join('')}${props.tags.map(tag => tag.name).join('')}${
				sortingMethods.length
			}`,
		];
	}, [props.nodes, props.tags]);

	const [ascending, setAscending] = useStickyState(
		false,
		STORAGE_KEYS.labAscending,
		{version},
	);
	const [sortIdx, setSortIdx] = useStickyState(0, STORAGE_KEYS.labSortIdx, {
		version,
	});
	const [typeStates, setTypeStates] = useStickyState(
		() => Array.from(nodeTypes).fill(true),
		STORAGE_KEYS.labTypeStates,
		{version, serverState: []},
	);
	const [tagMatch, setTagMatch] = useStickyState(
		'any',
		STORAGE_KEYS.labTagMatch,
		{version, serverState: 'any'},
	);
	const [tagStates, setTagStates] = useStickyState(
		() => Array.from(props.tags).fill(false),
		STORAGE_KEYS.labTagStates,
		{version, serverState: []},
	);

	const nSources =
		typeStates.reduce((a, b) => a + b, 0) || typeStates.length;

	const nodes = useMemo(() => {
		if (!typeStates.length) return null;
		const {sortFn} = sortingMethods[sortIdx];
		const checkedTypeNames = nodeTypes.filter((_, i) => typeStates[i]);
		const checkedTagNames = props.tags
			.filter((_, i) => tagStates[i])
			.map(tag => tag.name);
		const [doodles, filtered] = (
			checkedTypeNames.length
				? props.nodes.filter(node =>
						checkedTypeNames.includes(node.type),
					)
				: props.nodes
		)
			.filter(
				node =>
					!checkedTagNames.length ||
					checkedTagNames[tagMatch === 'any' ? 'some' : 'every'](
						tagName => node.tags?.includes(tagName),
					),
			)
			.reduce(
				(partitions, node) => {
					partitions[node.type === 'doodle' ? 0 : 1].push(node);
					return partitions;
				},
				[[], []],
			);
		const sorted = sortFn(filtered);
		const ordered = ascending ? sorted.reverse() : sorted;
		// Insert a few doodles into a random position.
		doodles.forEach(doodle => {
			const {shouldRender, ...rest} = doodle;
			if (shouldRender()) {
				ordered.splice(
					Math.floor(Math.random() * ordered.length),
					0,
					rest,
				);
			}
		});
		return ordered;
	}, [
		ascending,
		sortIdx,
		typeStates,
		tagMatch,
		tagStates,
		props.nodes,
		props.tags,
	]);

	const [shuffleId, setShuffleId] = useState(0);
	// Changing the sort or filters recomputes `nodes`, which clears the
	// shuffle.
	useEffect(() => setShuffleId(0), [nodes]);
	const displayNodes = useMemo(
		() => (shuffleId && nodes ? shuffle(nodes) : nodes),
		[nodes, shuffleId],
	);

	return (
		displayNodes && (
			<div className="project-explorer">
				<div className="filters-wrapper">
					<div className="filters">
						<fieldset>
							<legend>Show:</legend>
							<div className="inputs">
								{nodeTypes.map((type, i) => (
									<Fragment key={type}>
										<input
											className="visually-hidden"
											type="checkbox"
											name={`labs-types-${type}`}
											id={`labs-types-${type}`}
											value={type}
											checked={typeStates[i]}
											onChange={e => {
												const {checked} = e.target;
												setTypeStates(
													prevTypeStates => {
														const updatedTypeStates =
															[
																...prevTypeStates,
															];
														updatedTypeStates[i] =
															checked;
														return updatedTypeStates;
													},
												);
											}}
										/>
										<label htmlFor={`labs-types-${type}`}>
											{`${contentTypes[type].readableType}s`}
										</label>
									</Fragment>
								))}
							</div>
							<button
								className="labs-clear labs-clear-types"
								onClick={() =>
									setTypeStates(
										new Array(nodeTypes.length).fill(
											false,
										),
									)
								}
							>
								✖
							</button>
						</fieldset>
						<fieldset>
							<legend>Sort by:</legend>
							<div className="inputs">
								{sortingMethods.map(({title}, i) => (
									<Fragment key={title}>
										<input
											className="visually-hidden"
											type="radio"
											name={`labs-sort-${title}`}
											id={`labs-sort-${title}`}
											value={title}
											checked={sortIdx === i}
											onChange={() => setSortIdx(i)}
										/>
										<label htmlFor={`labs-sort-${title}`}>
											{capitalize(title)}
										</label>
									</Fragment>
								))}
							</div>
						</fieldset>
						<fieldset>
							<legend>Tags:</legend>
							<div className="inputs">
								{['any', 'all'].map(match => (
									<Fragment key={match}>
										<input
											className="visually-hidden"
											type="radio"
											name="labs-tag-match"
											id={`labs-tag-match-${match}`}
											value={match}
											checked={tagMatch === match}
											onChange={() => setTagMatch(match)}
										/>
										<label
											htmlFor={`labs-tag-match-${match}`}
										>
											{capitalize(match)}
										</label>
									</Fragment>
								))}
								{props.tags.map((tag, i) => (
									<Fragment key={tag.name}>
										<input
											className="visually-hidden"
											type="checkbox"
											name={`labs-tags-${tag.name}`}
											id={`labs-tags-${tag.name}`}
											value={tag.name}
											checked={tagStates[i]}
											onChange={e => {
												const {checked} = e.target;
												setTagStates(prevTagStates => {
													const updatedTagStates = [
														...prevTagStates,
													];
													updatedTagStates[i] =
														checked;
													return updatedTagStates;
												});
											}}
										/>
										<label
											htmlFor={`labs-tags-${tag.name}`}
										>
											{tag.readable}
										</label>
									</Fragment>
								))}
							</div>
							<button
								className="labs-clear labs-clear-tags"
								onClick={() =>
									setTagStates(
										new Array(props.tags.length).fill(
											false,
										),
									)
								}
							>
								✖
							</button>
						</fieldset>
						<fieldset>
							<legend>Order:</legend>
							<div className="inputs">
								<input
									className="visually-hidden"
									type="checkbox"
									name="labs-order"
									id="labs-order"
									value="ascending"
									checked={ascending}
									onChange={e =>
										setAscending(e.target.checked)
									}
								/>
								<label htmlFor="labs-order">Reverse</label>
								<button
									onClick={() => setShuffleId(id => id + 1)}
								>
									Shuffle
								</button>
							</div>
						</fieldset>
					</div>
					<p className="result-details">
						Found <strong>{displayNodes.length}</strong> entries
						from <strong>{nSources}</strong> source
						{nSources === 1 ? '' : 's'}:
					</p>
				</div>
				<LazyGrid
					nodes={displayNodes}
					setIsFullyLoaded={props.setIsFullyLoaded}
				/>
			</div>
		)
	);
});

const LazyGrid = React.memo(({nodes, setIsFullyLoaded}) => {
	const [renderLimit, setRenderLimit] = useState(20);
	const [ref, inView, boundingClientRect] = useViewport({
		trackPosition: true,
	});

	// If the last node is on or above the viewport, load the next 20 nodes.
	// Note that the “last” node might be higher up on the page, eg. if it has
	// a small footprint and squeezes into some top row masonry. Hence the on
	// *or above* the viewport check.
	useEffect(() => {
		if (
			(inView || boundingClientRect?.bottom <= 0) &&
			renderLimit < nodes.length
		) {
			setRenderLimit(l => l + 20);
		}
	}, [inView, boundingClientRect]);

	useEffect(() => {
		setRenderLimit(20);
	}, [nodes]);

	useEffect(() => {
		setIsFullyLoaded && setIsFullyLoaded(renderLimit >= nodes.length);
	}, [nodes.length, renderLimit]);

	return (
		<ContentGrid
			masonry
			nodes={nodes.slice(0, renderLimit)}
			hiddenNodes={nodes.slice(renderLimit)}
			lazyLoadRef={ref}
		/>
	);
});

const ProjectExplorerWrapper = React.memo(props => {
	const {
		allTagsJson: {nodes: tags},
		labProjects: {nodes: allProjects},
	} = useStaticQuery(graphql`
		{
			allTagsJson {
				nodes {
					name
					readable
				}
			}
			# Types that only belong on the blog are excluded at build time.
			labProjects: allCombinedProjectsJson(
				filter: {type: {nin: ["tumblr", "commit"]}}
				sort: {date: DESC}
			) {
				nodes {
					uid
					type
					title
					coolness
					date
					link
					description
					tags
					repo
					updatedAt
					length
					contentType
					body
					image {
						height
						width
						url
					}
					extraData
				}
			}
		}
	`);
	const nodes = useMemo(
		() =>
			allProjects.concat(
				gridDoodles.map(([Doodle, shouldRender], i) => ({
					uid: `DOODLE_${i}`,
					type: 'doodle',
					Doodle,
					shouldRender,
				})),
			),
		[allProjects],
	);

	return <ProjectExplorer nodes={nodes} tags={tags} {...props} />;
});

export default ProjectExplorerWrapper;
